//! Block drops (clk-misc, 2026-10-20): what a broken block drops, from the game's loot tables
//! (`loot_gen.rs`, generated by `redsim-fuzz loot-gen`), for a block broken with no tool and no
//! explosion radius: `Block.dropResources` (a block a neighbor update or a piston destroys) and a
//! TNT explosion (`tnt_explosion_drop_decay` off). Wall variants use their floor block's table;
//! blocks without a table (`noLootTable`: piston heads, moving pistons, fluids, end portal frames)
//! drop nothing.

use crate::block::Block;

/// Blocks that have no loot table (`noLootTable()` or no item): they drop nothing.
const NO_TABLE: [&str; 9] = ["air", "cave_air", "void_air", "piston_head", "moving_piston", "water", "bubble_column", "end_portal_frame", "lava"];

/// The stacks (item id `minecraft:...`, count) block `b` drops, or why redsim cannot say (a table
/// that draws from the loot random, or none known).
pub fn drops(b: &Block) -> Result<Vec<(String, u32)>, String> {
    let full = b.to_string();
    let s = full.strip_prefix("minecraft:").unwrap_or(&full);
    let (name, props) = match s.find('[') {
        Some(i) => (&s[..i], s[i + 1..].trim_end_matches(']')),
        None => (s, ""),
    };
    if NO_TABLE.contains(&name) {
        return Ok(Vec::new());
    }
    let kv: Vec<(&str, &str)> = props.split(',').filter_map(|p| p.split_once('=')).collect();
    let p = |k: &str| -> String { kv.iter().find(|(kk, _)| *kk == k).map(|(_, v)| v.to_string()).unwrap_or_default() };
    // a bed's table drops the bed from its head only (`block_state_property part=head`)
    if name.ends_with("_bed") {
        return Ok(if p("part") == "head" { vec![(format!("minecraft:{name}"), 1)] } else { Vec::new() });
    }
    let floor = name.replacen("_wall_", "_", 1);
    for n in [name, floor.as_str()] {
        if let Some(r) = crate::loot_gen::table(n, &p) {
            return r.map(|v| v.into_iter().map(|(i, c)| (format!("minecraft:{i}"), c)).collect()).map_err(|e| format!("the drops of {name}: {e}"));
        }
    }
    Err(format!("the drops of {name}: no loot table known to redsim"))
}

/// `Item.getDefaultMaxStackSize` for the items redsim drops: 64 except shulker boxes (1) and the
/// 16-stacks.
pub fn max_stack(item: &str) -> u32 {
    let n = item.strip_prefix("minecraft:").unwrap_or(item);
    if n.ends_with("shulker_box") {
        1
    } else if n.ends_with("banner") || n == "snowball" || n == "ender_pearl" || n == "egg" || n.ends_with("_sign") {
        16
    } else {
        64
    }
}
